import React from "react";
import "./Landlord.css"; // Import external CSS

export default function Landlord() {
  const landlords = [
    {
      name: "Rizal Boardinghouse",
      address: "Gen. Luna, La Paz Iloilo city",
      avatar: "avatar1.png",
    },
    {
      name: "Shiena Boardinghouse",
      address: "Barangay Bakhaw, Mandurriao Iloilo city",
      avatar: "avatar2.png",
    },
    {
      name: "Tanya Boardinghouse",
      address: "Brgy Tacas, Jaro, Iloilo city",
      avatar: "avatar3.png",
    },
    {
      name: "Sarrah Boardinghouse",
      address: "Iloilo city",
      avatar: "avatar4.png",
    },
  ];

  return (
    <div className="bg-white text-black min-h-screen">
      {/* Navigation Bar */}
      <nav className="navbar">
        <div className="nav-left">
          <img src="renter go.jpg" alt="logo" className="logo" />
          
        </div>
        <div>
          <img src="profile-icon.png" alt="Profile" className="profile-icon" />
        </div>
      </nav>

      {/* Main Content */}
      <section className="main-section">
        <h2 className="section-title">See Landlords Info</h2>

        <div className="landlord-list">
          {landlords.map((landlord, index) => (
            <div key={index} className="landlord-card">
              <div className="landlord-info">
                <img
                  src={landlord.avatar}
                  alt="Avatar"
                  className="avatar"
                />
                <div>
                  <p className="landlord-name">
                    {landlord.name}
                    <span className="verified-dot">●</span>
                  </p>
                  <p className="landlord-address">{landlord.address}</p>
                </div>
              </div>
              <p className="arrow">&gt;</p>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}
